const sysId = "vagabond-app";
const flag = "miserybusiness";
const featId = "Compendium.vagabond-app.features.Item.vb6J3WCDgCnV1K9m";

let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.getFlag(sysId, flag))?.actor;
}

if (!hero || !hero.getFlag(sysId, flag)) return;

game.system.api.rules.toggleEffect(hero, featId);
